{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Cicaprost, a prostacyclin analogue sharing the cyclopentane core and carboxyalkoxy side chain with the query, showed complete absolute oral bioavailability in healthy volunteers, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Iloprost, another prostacyclin analogue, had absolute oral bioavailability of 56-63% in patients, supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "FK788, a phenoxyacetic acid-containing bicyclic compound, was well absorbed with 55% oral bioavailability in healthy volunteers, supporting high F for the query's phenoxyacetic acid motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Pentopril, an oral carboxylic acid-containing drug, showed 50-70% bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Pravastatin, a carboxylic acid-containing drug, had only 17-19% oral bioavailability in humans; this is contradictory evidence but less transferable because it lacks the prostaglandin/prostacyclin scaffold and its low F is mechanism-specific.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a prostaglandin/prostacyclin-like molecule with a phenoxyacetic acid and multiple hydroxyls. The most transferable experimental evidence comes from cicaprost and iloprost, prostacyclin analogues with complete or 56-63% oral bioavailability, and from phenoxyacetic acid-containing compounds with high F. The low-F pravastatin evidence is less structurally relevant. Therefore predict high (F >= 20%).",
  "evidence_gaps": [
    "No direct fed-state pharmacokinetic data for the query or close analogues.",
    "Morgan similarities to evidence molecules are low, limiting quantitative transferability.",
    "Possible first-pass metabolism or transporter-mediated clearance in humans is not directly measured for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

